<?php
namespace App\Repositories;
use App\Models\ColaboradorCatalogo; use App\Models\EspecialidadCatalogo; use App\Models\Paciente; use App\Models\Sucursal; use App\Models\CitaDetalle; use MongoDB\Laravel\Eloquent\Model; use MongoDB\BSON\ObjectId;
class CitaCatalogoRepository {
 public function existe(string $tipo,string $id): bool { $m=match($tipo){'paciente'=>Paciente::class,'colaborador'=>ColaboradorCatalogo::class,'sucursal'=>Sucursal::class,'especialidad'=>EspecialidadCatalogo::class,'producto'=>CitaDetalle::class}; if($tipo==='producto') return (new class extends Model {protected $connection='mongodb'; protected $table='Tbl_Productos';})->newQuery()->where('_id',new ObjectId(strtolower($id)))->exists(); return $m::where('_id',new ObjectId(strtolower($id)))->exists(); }
 public function colaboradores(){return ColaboradorCatalogo::query()->orderBy('Apellidos')->get()->map(fn($x)=>['id'=>(string)$x->getKey(),'CodigoColaborador'=>(string)$x->getKey(),'Nombres'=>$x->Nombres,'Apellidos'=>$x->Apellidos,'NombreCompleto'=>trim(($x->Nombres??'').' '.($x->Apellidos??'')),'Estado'=>$x->Estado??null]);}
 public function especialidades(){return EspecialidadCatalogo::query()->orderBy('NombreEspecialidad')->get()->map(fn($x)=>['id'=>(string)$x->getKey(),'CodigoEspecialidad'=>(string)$x->getKey(),'NombreEspecialidad'=>$x->NombreEspecialidad,'Descripcion'=>$x->Descripcion??null,'Estado'=>$x->Estado??null]);}
 public function descripciones(array $citas): array { $ids=['CodigoPaciente'=>[],'CodigoColaborador'=>[],'CodigoSucursal'=>[],'CodigoEspecialidad'=>[]]; foreach($citas as $c) foreach(array_keys($ids) as $k) if(isset($c[$k])) $ids[$k][]=(string)$c[$k]; $sets=[ 'CodigoPaciente'=>\App\Models\Paciente::class, 'CodigoColaborador'=>ColaboradorCatalogo::class, 'CodigoSucursal'=>Sucursal::class, 'CodigoEspecialidad'=>EspecialidadCatalogo::class ]; $out=[]; foreach($sets as $k=>$model){$out[$k]=[]; foreach($model::whereIn('_id',array_map(fn($id)=>new ObjectId(strtolower($id)),array_unique($ids[$k])))->get() as $m){$name=match($k){'CodigoPaciente'=>trim(($m->Nombres??'').' '.($m->Apellidos??'')),'CodigoColaborador'=>trim(($m->Nombres??'').' '.($m->Apellidos??'')),'CodigoSucursal'=>$m->nombre??$m->NombreSucursal??'','CodigoEspecialidad'=>$m->NombreEspecialidad??''}; $out[$k][(string)$m->getKey()]=$name;}} return $out; }
}
